// Solution for: City Cab Fare Meter
import java.util.*; public class W92_q4 {public static void main(String[]z){Scanner s=new Scanner(System.in);int n=s.nextInt();double total=0;for(int i=0;i<n;i++){String t=s.next().toUpperCase();double km=s.nextDouble();String time=s.next().toUpperCase();if(t.equals("MINI")&&time.equals("NIGHT")){System.out.println("MINI: night service not available");continue;}double rate=t.equals("MINI")?10:t.equals("SEDAN")?14:18;double fare=Math.max(100,km*rate);if(time.equals("NIGHT"))fare*=1.2;System.out.printf("%s: %.2f%n",t,fare);total+=fare;}System.out.printf("Total: %.2f%n",total);}}
